    @Test void ActualWholeDailyGroupsAndImmutableReferenceClosureFreezeOneOriginalCatalogBody()throws Exception {nativeSetup("agent");var value=capture();assertNotNull(value);assertTrue(value.sourceProof().complete());assertEquals(1,value.sourceProof().candidates().size());assertTrue(value.sourceProof().missingInputs().isEmpty());assertTrue(value.sourceProof().noUpdateDates().isEmpty());assertEquals(1,value.referenceTargetsByEvidence().size());assertEquals(1,value.dependencies().size());assertSame(value,rr(()->service.verifyObserved(value)));var command=new GenerationFlowService.Prepare("fictional-complete-daily",1,GenerationFlowService.Stage.DAILY_REPORT,value.day(),null,List.of(),List.of(),List.of(),false,"a".repeat(64));var frozen=new ReportInputSnapshotService((c,t)->value.sourceProof()).freeze(command,value.cutoff());assertTrue(frozen.hasContent());assertEquals("complete",frozen.coverageState());assertEquals(data.nativeData().completed().bodyJson(),JdbcFrozenInputs.canonical(CanonicalJson.parse(frozen.snapshotJson()).get("members").get(0).get("body")));assertEquals(2,data.nativeData().fixture().f().sends);assertTrue(value.originalByteSize()>data.nativeData().completed().bodyJson().getBytes(java.nio.charset.StandardCharsets.UTF_8).length);assertThrows(UnsupportedOperationException.class,()->value.referenceTargetsByEvidence().clear());assertThrows(UnsupportedOperationException.class,()->value.sourceProof().candidates().clear());assertFalse(value.toString().contains("fictional"));}
