    @Test void AnotherActualOriginalDirectoryCannotBeCombinedAtTheSameDayAndCutoff()throws Exception {nativeSetup("skill");var foreign=new NewsDayReportComponentTest();foreign.setup();var at=data.nativeData().fixture().day().plusDays(1).atTime(0,10).atZone(ZoneId.of("Asia/Shanghai")).toInstant();foreign.cohorts=foreign.h.service(()->new com.lianxibu.site.domain.sources.SourceDayRoster.Evidence(at,0,List.of()),Clock.fixed(at,ZoneOffset.UTC));foreign.service=foreign.create(foreign.cohorts,foreign.barrier);foreign.cohorts.seal(data.nativeData().fixture().day());var captured=foreign.service.capture(data.nativeData().fixture().day(),data.nativeData().cutoff());assertNotNull(captured);var fault=mock(NewsDayReportComponentService.class);when(fault.capture(any(),any())).thenReturn(captured);when(fault.verifyObserved(captured)).thenReturn(captured);var consumer=new DailyReportInputComponentService(fault,data.service(),heat,data.nativeData().fixture().f().tx);assertThrows(RuntimeException.class,()->consumer.capture(data.nativeData().fixture().day(),data.nativeData().cutoff()));}
    @Test void CompleteBudgetForeignIssuerAndExplicitTransactionBoundariesAreMandatory()throws Exception {nativeSetup("workflow");var value=capture();assertThrows(GenerationFlowService.CapacityGuarded.class,()->create(1024).capture(value.day(),value.cutoff()));assertThrows(RuntimeException.class,()->service.verifyObserved(value));assertThrows(RuntimeException.class,()->rr(()->create(EntityHeatCutoffProofService.MAX_ORIGINAL_BYTES).verifyObserved(value)));assertThrows(RuntimeException.class,()->rr(this::capture));assertThrows(RuntimeException.class,()->service.capture(value.day(),value.cutoff().plusNanos(1000)));assertSame(value,rr(()->service.verifyObserved(value)));}
